        return rocblas_set_optimal_device_memory_size(handle,
                                                     size_scalars,
                                                     size_work_workArr,
                                                     size_Abyx_norms,
                                                     size_diag);

    // Step 6: Allocate device workspace
    void *scalars, *work_workArr, *Abyx_norms, *diag;
    rocblas_device_malloc mem(handle,
                             size_scalars,
                             size_work_workArr,
                             size_Abyx_norms,
                             size_diag);

    if(!mem)
        return rocblas_status_memory_error;

    // Step 7: Assign workspace pointers
    scalars = mem[0];
    work_workArr = mem[1];
    Abyx_norms = mem[2];
    diag = mem[3];

    // Step 8: Initialize scalar constants
    if(size_scalars > 0)
        init_scalars(handle, (T*)scalars);

    // Step 9: Execute algorithm
    return rocsolver_gerq2_template<T>(handle,
                                      m, n,
                                      A, shiftA, lda, strideA,
                                      ipiv, stridep,
                                      batch_count,
                                      (T*)scalars,
                                      work_workArr,
                                      (T*)Abyx_norms,
                                      (T*)diag);
}

